import { test, expect } from '@playwright/test'
import { ADMIN_AUTH, UNREGISTERED_AUTH, API_BASE } from '../auth.helpers'

test.describe('US1 scenario 1+2 — admin signs in and is recognized', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — admin OAuth completes and app is accessible', async ({ page }) => {
    await page.goto('/')
    await expect(page).not.toHaveURL(/\/signin/)
    await expect(page.getByRole('main', { name: /kanban board/i })).toBeVisible()
  })

  test('scenario 2 — subsequent sign-in is recognized; /auth/me returns admin role', async ({
    page,
  }) => {
    await page.goto('/')
    await expect(page).not.toHaveURL(/\/signin/)

    const resp = await page.request.get(`${API_BASE}/api/v1/auth/me`)
    expect(resp.status()).toBe(200)
    const body = await resp.json()
    expect(body.systemRole).toBe('admin')
  })
})

test.describe('US1 scenario 3 — non-registered Google user sees not-registered page', () => {
  test.use({ storageState: UNREGISTERED_AUTH })

  test('scenario 3 — non-invited account is redirected to /not-registered with no app data', async ({
    page,
  }) => {
    await page.goto('/')
    await expect(page).toHaveURL(/\/not-registered/)
    await expect(
      page.getByRole('heading', { name: /not registered|access denied/i }),
    ).toBeVisible()
    await expect(page.getByRole('navigation')).not.toBeVisible()
  })
})

test.describe('US1 scenario 4 — unauthenticated access redirects to sign-in', () => {
  test('scenario 4 — unauthenticated root navigates to /signin', async ({ browser }) => {
    const ctx = await browser.newContext()
    const page = await ctx.newPage()
    await page.goto('/')
    await expect(page).toHaveURL(/\/signin/)
    await expect(page.getByRole('heading', { name: /sign in/i })).toBeVisible()
    await expect(page.getByRole('link', { name: /sign in with google/i })).toBeVisible()
    await ctx.close()
  })
})

import { test as setup, expect } from '@playwright/test'
import fs from 'fs'
import {
  ADMIN_AUTH, INVITEE_AUTH, UNREGISTERED_AUTH,
  API_BASE, WEB_BASE,
  ADMIN_EMAIL, INVITEE_EMAIL, UNREGISTERED_EMAIL,
} from './auth.helpers'

const BYPASS = process.env.PLAYWRIGHT_AUTH_BYPASS === 'true'

setup.beforeAll(() => {
  fs.mkdirSync('playwright/.auth', { recursive: true })
})

// ── CI / bypass path ──────────────────────────────────────────────────────────
// Calls GET /api/v1/dev/authenticate which issues the cookie without Google OAuth
// and redirects to the frontend. Only registered when ASPNETCORE_ENVIRONMENT=Development.

setup('bypass: authenticate as admin', async ({ page }) => {
  setup.skip(!BYPASS, 'bypass path only — run with PLAYWRIGHT_AUTH_BYPASS=true')
  await page.goto(`${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(ADMIN_EMAIL)}`)
  await page.waitForURL(`${WEB_BASE}/**`)
  await page.context().storageState({ path: ADMIN_AUTH })
})

setup('bypass: authenticate as unregistered invitee', async ({ page }) => {
  setup.skip(!BYPASS, 'bypass path only — run with PLAYWRIGHT_AUTH_BYPASS=true')
  await page.goto(
    `${API_BASE}/api/v1/dev/authenticate` +
    `?email=${encodeURIComponent(INVITEE_EMAIL)}&displayName=Playwright+Invitee`,
  )
  await page.waitForURL(`${WEB_BASE}/**`)
  await page.context().storageState({ path: INVITEE_AUTH })
})

setup('bypass: authenticate as unregistered non-invited user', async ({ page }) => {
  setup.skip(!BYPASS, 'bypass path only — run with PLAYWRIGHT_AUTH_BYPASS=true')
  await page.goto(
    `${API_BASE}/api/v1/dev/authenticate` +
    `?email=${encodeURIComponent(UNREGISTERED_EMAIL)}&displayName=Playwright+Unregistered`,
  )
  await page.waitForURL(`${WEB_BASE}/**`)
  await page.context().storageState({ path: UNREGISTERED_AUTH })
})

// ── Demo / real Google path ───────────────────────────────────────────────────
// Opens a headed browser window and waits (up to 2 minutes) for you to complete
// Google sign-in manually. Run once with: npm run test:e2e:setup
// The saved state is reused for all subsequent demo runs.

setup('google: authenticate as admin', async ({ page, context }) => {
  setup.skip(BYPASS, 'real Google path only — run without PLAYWRIGHT_AUTH_BYPASS=true')
  setup.setTimeout(180_000)
  await page.goto(`${WEB_BASE}/signin`)
  await expect(page.getByRole('link', { name: /sign in with google/i })).toBeVisible()
  await page.click('a[href*="/api/v1/auth/signin"]')
  // Wait up to 3 minutes for the user to complete Google sign-in in the browser window
  await page.waitForURL(`${WEB_BASE}/**`, { timeout: 170_000 })
  await expect(page).not.toHaveURL(/\/signin/)
  await context.storageState({ path: ADMIN_AUTH })
})

import { test, expect } from '@playwright/test'
import {
  ADMIN_AUTH, INVITEE_AUTH,
  API_BASE, WEB_BASE,
  ADMIN_EMAIL, INVITEE_EMAIL,
} from '../auth.helpers'

// ── US2: Admin issues an invitation ──────────────────────────────────────────
// These scenarios require the board page (InviteUserDialog lives there).
// Scaffolded now; will be completed in the board feature spec.

test.describe('US2: Admin issues an invitation', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — admin submits valid email and receives redemption link', async ({ page }) => {
    test.fixme(true, 'Requires board page — InviteUserDialog not yet accessible')
    await page.goto('/')
    await expect(page.getByRole('main', { name: /kanban board/i })).toBeVisible()
  })

  test('scenario 2 — re-invite of unconsumed email returns existing link without duplicate', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })

  test('scenario 3 — re-invite of expired email issues fresh invitation', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })

  test('scenario 4 — non-admin user is refused with permission denied', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })

  test('scenario 5 — invalid email format is rejected with validation error', async ({ page }) => {
    test.fixme(true, 'Requires board page')
    await page.goto('/')
  })
})

// ── US3: Invitee accepts an invitation ───────────────────────────────────────

test.describe('US3: Invitee accepts an invitation', () => {
  test('scenario 1 — valid token with matching email creates registered user', async ({
    browser,
    request,
  }) => {
    const uniqueEmail = `invitee-${Date.now()}@example.com`

    const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
      data: { email: uniqueEmail, adminEmail: ADMIN_EMAIL },
    })
    expect(seedResp.ok()).toBeTruthy()
    const { token } = await seedResp.json()

    const ctx = await browser.newContext()
    const page = await ctx.newPage()
    await page.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(uniqueEmail)}&displayName=Scenario+1+Invitee`,
    )
    await page.waitForURL(`${WEB_BASE}/**`)

    await page.goto(`${WEB_BASE}/accept/${token}`)
    await expect(page).toHaveURL(`${WEB_BASE}/`, { timeout: 15_000 })
    await expect(page.getByRole('main', { name: /kanban board/i })).toBeVisible()

    await ctx.close()
  })

  test('scenario 2 — invitee can sign in via regular flow after accepting', async ({ page }) => {
    test.fixme(true, 'Depends on scenario 1 having registered the invitee; requires board page for full verification')
    await page.goto('/')
  })

  test.describe('error states — use invitee auth cookie', () => {
    test.use({ storageState: INVITEE_AUTH })

    test('scenario 3 — expired token shows invitation-no-longer-valid error', async ({
      page,
      request,
    }) => {
      const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
        data: { email: INVITEE_EMAIL, adminEmail: ADMIN_EMAIL, expiresInDays: -1 },
      })
      const { token } = await seedResp.json()

      await page.goto(`${WEB_BASE}/accept/${token}`)
      await expect(
        page.getByRole('status').filter({ hasText: /no longer valid|invite\.invalid/i }),
      ).toBeVisible({ timeout: 10_000 })
    })

    test('scenario 4 — consumed token shows same invalid message as expired', async ({
      page,
      request,
    }) => {
      const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
        data: { email: INVITEE_EMAIL, adminEmail: ADMIN_EMAIL, consumed: true },
      })
      const { token } = await seedResp.json()

      await page.goto(`${WEB_BASE}/accept/${token}`)
      await expect(
        page.getByRole('status').filter({ hasText: /no longer valid|invite\.invalid/i }),
      ).toBeVisible({ timeout: 10_000 })
    })

    test('scenario 5 — email mismatch shows different email address message', async ({
      page,
      request,
    }) => {
      // Invitation is for a different email; cookie is for INVITEE_EMAIL
      const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed/invitation`, {
        data: { email: 'different-addressee@example.com', adminEmail: ADMIN_EMAIL },
      })
      const { token } = await seedResp.json()

      await page.goto(`${WEB_BASE}/accept/${token}`)
      await expect(
        page.getByRole('status').filter({ hasText: /different email|invite\.email_mismatch/i }),
      ).toBeVisible({ timeout: 10_000 })
    })

    test('scenario 6 — fabricated token shows same invalid message', async ({ page }) => {
      const fakeToken = 'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA'
      await page.goto(`${WEB_BASE}/accept/${fakeToken}`)
      await expect(
        page.getByRole('status').filter({ hasText: /no longer valid|invite\.invalid/i }),
      ).toBeVisible({ timeout: 10_000 })
    })
  })
})

