35	var builder = WebApplication.CreateBuilder(args);
36	
37	// ── Options — fail at boot if configuration is missing ────────────────────────
38	
39	builder.Services.AddOptions<GoogleAuthOptions>()
40	    .Bind(builder.Configuration.GetSection(GoogleAuthOptions.SectionName))
41	    .ValidateDataAnnotations()
42	    .ValidateOnStart();
43	
44	builder.Services.AddOptions<SeedOptions>()
45	    .Bind(builder.Configuration.GetSection(SeedOptions.SectionName))
46	    .ValidateDataAnnotations()
47	    .ValidateOnStart();
48	
49	builder.Services.AddOptions<CorsOptions>()
50	    .Bind(builder.Configuration.GetSection(CorsOptions.SectionName))
51	    .ValidateDataAnnotations()
52	    .ValidateOnStart();
53	
54	builder.Services.AddOptions<ConnectionStringOptions>()
55	    .Bind(builder.Configuration.GetSection(ConnectionStringOptions.SectionName))
56	    .ValidateDataAnnotations()
57	    .ValidateOnStart();
58	
59	// ── Database ──────────────────────────────────────────────────────────────────
60	
61	DapperConfiguration.RegisterTypeHandlers();
62	
63	// Resolve the connection string lazily from IOptions so that WebApplicationFactory
64	// configuration overrides (applied after builder services are registered) are honoured.
65	builder.Services.AddScoped<IDbConnection>(sp =>
66	{
67	    var opts = sp.GetRequiredService<IOptions<ConnectionStringOptions>>().Value;
68	    var conn = new SqliteConnection(opts.Kanban);
69	    conn.Open();
70	    using var cmd = conn.CreateCommand();
71	    cmd.CommandText = "PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;";
72	    cmd.ExecuteNonQuery();
73	    return conn;
74	});
75	
76	// ── Exception Handling ────────────────────────────────────────────────────────
77	
78	builder.Services.AddProblemDetails(options =>
79	{
80	    options.CustomizeProblemDetails = ctx =>
81	    {
82	        ctx.ProblemDetails.Extensions["traceId"] = Activity.Current?.Id;
83	        if (ctx.HttpContext.Response.StatusCode == StatusCodes.Status403Forbidden
84	            && !ctx.ProblemDetails.Extensions.ContainsKey("code"))
85	        {
86	            ctx.ProblemDetails.Title = "You are not registered to use this application.";
87	            ctx.ProblemDetails.Extensions["code"] = "user.not_registered";
88	        }
89	    };
90	});
91	builder.Services.AddExceptionHandler<DomainExceptionHandler>();
92	builder.Services.AddExceptionHandler<InfrastructureExceptionHandler>();
93	builder.Services.AddExceptionHandler<FallbackExceptionHandler>();
94	
95	// ── CORS ──────────────────────────────────────────────────────────────────────
96	
97	builder.Services.AddCors(options =>
98	    options.AddPolicy("KanbanWebApp", policy =>
99	        policy
100	            .WithOrigins(
101	                builder.Configuration
102	                    .GetSection("Cors:AllowedOrigins")
103	                    .Get<string[]>() ?? [])
104	            .WithMethods("GET", "POST", "PUT", "DELETE", "PATCH", "OPTIONS")
105	            .AllowAnyHeader()
106	            .WithExposedHeaders("X-Correlation-Id", "api-supported-versions")));
107	
108	// ── Authentication & Authorization ───────────────────────────────────────────
109	
110	builder.Services.AddScoped<ICurrentUserService, CurrentUserService>();
111	builder.Services.AddScoped<IAuthService, AuthService>();
112	builder.Services.AddScoped<IInvitationService, InvitationService>();
113	builder.Services.AddSingleton<IDbConnectionFactory, SqliteConnectionFactory>();
114	builder.Services.AddScoped<GoogleIdentityAdapter>();
115	builder.Services.AddScoped<IUserRepository, UserRepository>();
116	builder.Services.AddScoped<IAuthEventRepository, AuthEventRepository>();
117	builder.Services.AddScoped<IInvitationRepository, InvitationRepository>();
118	builder.Services.AddValidatorsFromAssemblyContaining<IssueInviteRequestValidator>();
119	builder.Services.AddHttpContextAccessor();
120	builder.Services.AddScoped<IAuthorizationHandler, RegisteredUserHandler>();
121	
122	builder.Services.AddAuthentication(options =>
123	    {
124	        options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
