1	using System.Data;
2	using Kanban.Business.Interfaces;
3	using Kanban.Business.Transforms;
4	using Kanban.Contracts;
5	using Kanban.DataAccess.Interfaces;
6	using Kanban.Domain;
7	using Kanban.Domain.Entities;
8	using Kanban.Domain.Enums;
9	using Kanban.Domain.Events;
10	using Kanban.Domain.Exceptions;
11	using Kanban.Domain.ValueObjects;
12	using Microsoft.Extensions.Logging;
13	using Polly;
14	using Polly.Retry;
15	
16	namespace Kanban.Business.Services;
17	
18	public sealed class InvitationService : IInvitationService
19	{
20	    private readonly IUserRepository _userRepository;
21	    private readonly IInvitationRepository _invitationRepository;
22	    private readonly IAuthEventRepository _authEventRepository;
23	    private readonly IDbConnection _dbConnection;
24	    private readonly IDbConnectionFactory _transactionFactory;
25	    private readonly ILogger<InvitationService> _logger;
26	
27	    private static readonly ResiliencePipeline RetryPolicy =
28	        new ResiliencePipelineBuilder()
29	            .AddRetry(new RetryStrategyOptions
30	            {
31	                MaxRetryAttempts = 20,
32	                Delay = TimeSpan.FromMilliseconds(50),
33	                BackoffType = DelayBackoffType.Exponential,
34	                UseJitter = true,
35	                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
36	                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
37	                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
38	            })
39	            .Build();
40	
41	    public InvitationService(
42	        IUserRepository userRepository,
43	        IInvitationRepository invitationRepository,
44	        IAuthEventRepository authEventRepository,
45	        IDbConnection dbConnection,
46	        IDbConnectionFactory transactionFactory,
47	        ILogger<InvitationService> logger)
48	    {
49	        Verify.That(userRepository).IsNotNull();
50	        Verify.That(invitationRepository).IsNotNull();
51	        Verify.That(authEventRepository).IsNotNull();
52	        Verify.That(dbConnection).IsNotNull();
53	        Verify.That(transactionFactory).IsNotNull();
54	        Verify.That(logger).IsNotNull();
55	        _userRepository = userRepository;
56	        _invitationRepository = invitationRepository;
57	        _authEventRepository = authEventRepository;
58	        _dbConnection = dbConnection;
59	        _transactionFactory = transactionFactory;
60	        _logger = logger;
61	    }
62	
63	    public async Task<(IssueInviteResponse Response, bool IsNew)> IssueAsync(
64	        string email,
65	        Guid issuedByUserId,
66	        SystemRole callerRole,
67	        string frontendBaseUrl,
68	        CancellationToken cancellationToken = default)
69	    {
70	        Verify.That(email).IsNotNull().IsNotEmpty();
71	        Verify.That(issuedByUserId).IsNotDefault();
72	        Verify.That(frontendBaseUrl).IsNotNull().IsNotEmpty();
73	
74	        if (callerRole != SystemRole.Admin)
75	            throw new ForbiddenException("invite.forbidden", "Only admins can issue invitations.");
76	
77	        return await RetryPolicy.ExecuteAsync(async ct =>
78	        {
79	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
80	            try
81	            {
82	                var existing = await _invitationRepository.FindActiveByEmailAsync(email, tx);
83	                if (existing is not null)
84	                {
85	                    var refreshToken = InvitationToken.Generate();
86	                    var newExpiry = DateTimeOffset.UtcNow.AddDays(7);
87	                    await _invitationRepository.RefreshTokenAsync(
88	                        existing.Id, refreshToken.Hash, newExpiry, tx);
89	                    tx.Commit();
90	                    _logger.LogInformation(
91	                        "Active invitation refreshed by {IssuedByUserId}", issuedByUserId);
92	                    return (InvitationTransforms.ToResponse(refreshToken.Raw, newExpiry, frontendBaseUrl), false);
93	                }
94	
95	                var registeredUser = await _userRepository.FindByEmailAsync(email, tx);
96	                if (registeredUser is not null)
97	                    throw new ConflictException(
98	                        "invite.already_registered", "This email address is already registered.");
99	
100	                var token = InvitationToken.Generate();
101	                var issuedAt = DateTimeOffset.UtcNow;
102	                var invitation = new Invitation(
103	                    id: Guid.NewGuid(),
104	                    email: email,
105	                    issuedByUserId: issuedByUserId,
106	                    tokenHash: token.Hash,
107	                    issuedAt: issuedAt,
108	                    expiresAt: issuedAt.AddDays(7),
109	                    consumedAt: null,
110	                    consumedByUserId: null);
111	
112	                await _invitationRepository.InsertAsync(invitation, tx);
113	
114	                var authEvent = new AuthEvent(
115	                    Id: Guid.NewGuid(),
116	                    OccurredAt: issuedAt,
117	                    EventType: AuthEventType.InvitationIssued,
118	                    UserId: issuedByUserId,
119	                    Outcome: "success");
120	                await _authEventRepository.RecordAsync(authEvent, tx);
121	
122	                tx.Commit();
123	
124	                _logger.LogInformation(
125	                    "Invitation issued by {IssuedByUserId}", issuedByUserId);
126	
127	                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
128	            }
129	            catch
130	            {
131	                tx.Rollback();
132	                throw;
133	            }
134	        }, cancellationToken);
135	    }
136	
137	    public async Task<User> AcceptAsync(
138	        string rawToken,
139	        string googleEmail,
140	        string googleSub,
141	        string displayName,
142	        CancellationToken cancellationToken = default)
143	    {
144	        Verify.That(rawToken).IsNotNull().IsNotEmpty();
145	        Verify.That(googleEmail).IsNotNull().IsNotEmpty();
146	        Verify.That(googleSub).IsNotNull().IsNotEmpty();
147	        Verify.That(displayName).IsNotNull().IsNotEmpty();
148	
149	        return await RetryPolicy.ExecuteAsync(async ct =>
150	        {
151	            var tokenHash = InvitationToken.HashRaw(rawToken);
152	            var acceptedAt = DateTimeOffset.UtcNow;
153	            var newUserId = Guid.NewGuid();
154	
155	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
156	            try
157	            {
158	                // Atomic gate: marks consumed_at — serialises concurrent accepts.
159	                // consumed_by_user_id is set separately below (after user is created) to avoid
160	                // FK constraint violations in Microsoft.Data.Sqlite 10+ which enforces them by
161	                // default, unlike previous versions.
162	                var consumed = await _invitationRepository.TryConsumeAsync(tokenHash, acceptedAt, tx);
163	                if (!consumed)
164	                    throw new NotFoundException(
165	                        "invite.invalid",
166	                        "This invitation is no longer valid. Please request a new one.");
167	
168	                var invitation = await _invitationRepository.FindByTokenHashAsync(tokenHash, tx);
169	                if (invitation is null || !invitation.EmailMatches(googleEmail))
170	                    throw new BusinessRuleException(
171	                        "invite.email_mismatch",
172	                        "This invitation was issued to a different email address.");
173	
174	                var user = new User(
175	                    id: newUserId,
176	                    email: invitation.Email,
177	                    displayName: displayName,
178	                    systemRole: SystemRole.Standard,
179	                    googleSub: googleSub,
180	                    registeredAt: acceptedAt,
181	                    lastSignInAt: null);
182	
183	                await _userRepository.InsertAsync(user, tx);
184	
185	                // FK constraint satisfied now that the user row exists
186	                await _invitationRepository.RecordConsumerAsync(tokenHash, newUserId, tx);
187	
188	                var authEvent = new AuthEvent(
189	                    Id: Guid.NewGuid(),
190	                    OccurredAt: acceptedAt,
191	                    EventType: AuthEventType.InvitationAccepted,
192	                    UserId: newUserId,
193	                    Outcome: "success");
194	                await _authEventRepository.RecordAsync(authEvent, tx);
195	
196	                tx.Commit();
197	
198	                _logger.LogInformation("Invitation accepted by user {UserId}", newUserId);
199	                return user;
200	            }
201	            catch
202	            {
203	                tx.Rollback();
204	                throw;
205	            }
206	        }, cancellationToken);
207	    }
208	}
209

