    public void LinkGoogleIdentity(string googleSub)
    {
        Verify.That(googleSub).IsNotNull().IsNotEmpty();
        GoogleSub = googleSub;
    }

    public void RecordSignIn(DateTimeOffset signedInAt) => LastSignInAt = signedInAt;
}

